<script setup lang="ts">
import { ref, onMounted } from 'vue'
import { api } from './api'
const rules=ref<any[]>([]), selected=ref<any>(null), json=ref(''), reviewer=ref(''), note=ref(''), stage=ref('text'), busy=ref(false), error=ref(''), notice=ref('')
const sample={id:'',version:1,title:'',kind:'pattern',status:'draft',synthetic:false,scope:{description:''},required:{fact:'',state:'present'},support:[],evidence_ids:[],formula:[],actions:[],description:''}
async function run(fn:()=>Promise<void>){busy.value=true;error.value='';notice.value='';try{await fn()}catch(e){error.value=e instanceof Error?e.message:String(e)}finally{busy.value=false}}
async function refresh(){rules.value=(await api.request('/rules')).items;if(selected.value)selected.value=rules.value.find(r=>r.id===selected.value.id)||null}
function choose(rule:any){selected.value=rule;json.value=JSON.stringify(rule,null,2)}
function cloneDraft(){const source=JSON.parse(json.value);selected.value=null;json.value=JSON.stringify({...source,id:'',version:source.version+1,status:'draft',reviews:undefined,created_at:undefined},null,2)}
function newDraft(){selected.value=null;json.value=JSON.stringify(sample,null,2)}
async function create(){const rule=JSON.parse(json.value);if(rule.status!=='draft')throw Error('只能创建草稿。已发布规则须以新id和版本创建草稿');if(!rule.id?.trim()||!rule.title?.trim())throw Error('规则id和标题必填');delete rule.reviews;delete rule.created_at;await api.post('/rules',{rule});await refresh();choose(rules.value.find(r=>r.id===rule.id));notice.value='草稿已保存；尚未进入执行核心。'}
async function action(kind:'review'|'publish'|'withdraw'){if(!selected.value||!reviewer.value.trim()||!note.value.trim())throw Error('请选择规则并填写审核人和意见');await api.post(`/rules/${selected.value.id}/${kind}`,{reviewer:reviewer.value,note:note.value,...(kind==='review'?{stage:stage.value}:{})});await refresh();notice.value=kind==='publish'?'已发布 · 仅工程试算':kind==='withdraw'?'规则已撤回；历史快照仍保留。':'审核已记录。'}
onMounted(()=>run(async()=>{await refresh();newDraft()}))
</script>
<template><section aria-label="规则审核"><div class="section-head"><h2>受限规则与三级审核</h2><el-button @click="newDraft" :disabled="busy">新建规则草稿</el-button></div><p class="hint">规则只接受受限条件JSON；禁止任意脚本。非合成规则须有已校核真实证据。已发布版本不覆盖修改。</p><el-alert v-if="error" :title="error" type="error" :closable="false"/><el-alert v-if="notice" :title="notice" type="success" :closable="false"/>
<div class="rules-grid"><div class="panel"><h3>规则版本</h3><button v-for="r in rules" :key="r.id" class="rule-row" :class="{selected:selected?.id===r.id}" @click="choose(r)"><strong>{{r.title}}</strong><small>{{r.id}} · v{{r.version}} · {{r.kind}}</small><el-tag :type="r.status==='published'?'success':r.status==='withdrawn'?'info':'warning'">{{r.status==='published'?'已发布 · 仅工程试算':r.status==='draft'?'草稿':'已撤回'}}</el-tag><el-tag v-if="r.synthetic" type="warning">合成规则</el-tag></button><p class="empty" v-if="!rules.length">暂无规则</p></div><div class="panel"><h3>{{selected?'规则审阅':'创建草稿'}}</h3><label>规则 JSON<textarea v-model="json" rows="22" class="code-editor" spellcheck="false" :readonly="!!selected" :disabled="busy"></textarea></label><el-button v-if="!selected" type="primary" :loading="busy" @click="run(create)">验证并创建草稿</el-button><template v-if="selected"><h3>已有审核</h3><pre>{{JSON.stringify(selected.reviews,null,2)}}</pre><label>审核人<input v-model="reviewer" :disabled="busy"></label><label>审核意见<textarea v-model="note" rows="3" :disabled="busy"></textarea></label><label>审核阶段<select v-model="stage" :disabled="busy"><option value="text">一 · 文本校核</option><option value="semantic">二 · 规则语义</option><option value="clinical">三 · 临床适用</option></select></label><div class="button-row"><el-button :disabled="busy||selected.status!=='draft'" @click="run(()=>action('review'))">登记本阶段审核</el-button><el-button type="primary" :disabled="busy||selected.status!=='draft'" @click="run(()=>action('publish'))">审核完备后发布</el-button><el-button type="danger" plain :disabled="busy||selected.status!=='published'" @click="run(()=>action('withdraw'))">撤回已发布规则</el-button></div><p class="warning">发布需服务端确认三级审核与证据条件；合成规则始终只用于算法演示。</p><el-button @click="cloneDraft">以新id / 版本创建草稿</el-button></template></div></div></section></template>

